-- Роли страниц.
--
-- По §3.2 таблица состоит из кода и названия. Признаки распознавания ролей
-- остаются в коде (PAGE_ROLES): таблицы переопределений для них нет, а базе
-- справочник нужен ради внешних ключей.
INSERT INTO page_roles (code, name)
VALUES
  ($seed$annex_continuation$seed$, $seed$Приложение-продолжение документа$seed$),
  ($seed$blank$seed$, $seed$Пустая страница$seed$),
  ($seed$copy_stamp$seed$, $seed$Штамп «КОПИЯ ВЕРНА»$seed$),
  ($seed$doc_continuation$seed$, $seed$Продолжение многостраничного документа$seed$),
  ($seed$signature_visual$seed$, $seed$Лист визуализации электронной подписи$seed$)
ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name;
